import { cardsForArea, demoCases, findArea, findCard, findQuestion, prototypeAreas, questionBlocks, resultStates, type AreaId, type DemoCase, type EntryState, type OptionDef, type ResultStateDef, type StageId } from './prototypeKnowledge';
import { initialAreaForIntake, intakeApplicability, intakeDtcSignals, type IntakeProfile } from './prototypeIntake';

export interface RecordedAnswer{questionId:string;optionId:string;label:string;outcome:'normal'|'abnormal'|'unavailable'|'recovered';fields:Record<string,string>;note:string;caseId:string}
export interface KnowledgeState{caseId:string;pendingCaseId:string|null;confirmedIntake:IntakeProfile|null;frozenAreaOrder:AreaId[]|null;selectedAreaId:AreaId;selectedCardId:string;openQuestionId:string|null;answers:Record<string,RecordedAnswer>;historicalIds:string[];drafts:Record<string,Record<string,string>>;notes:Record<string,string>;showIntake:boolean;showRetest:boolean;showHistory:boolean;showAllIssues:boolean;expandedAreas:AreaId[];assetId:string|null;assetZoom:number;blank:boolean}
export type KnowledgeEvent={type:'confirm-intake';profile:IntakeProfile}|{type:'request-case';caseId:string}|{type:'cancel-case'}|{type:'confirm-case'}|{type:'reset-case'}|{type:'blank'}|{type:'select-area';areaId:AreaId}|{type:'select-card';cardId:string}|{type:'open-question';questionId:string}|{type:'update-draft';questionId:string;field:string;value:string}|{type:'update-note';questionId:string;value:string}|{type:'record';questionId:string;optionId:string}|{type:'correct';questionId:string}|{type:'toggle-intake'}|{type:'toggle-retest'}|{type:'toggle-history'}|{type:'toggle-issues'}|{type:'toggle-area';areaId:AreaId}|{type:'open-asset';assetId:string}|{type:'close-asset'}|{type:'zoom-asset';zoom:number};

const stageOrder:StageId[]=['S0','S1','S2','S3','S4','S5','S6'];
const required:Record<StageId,string[]>={S0:['IN-01','IN-02','IN-04','IN-08'],S1:['AIR-01','AIR-03','AIR-07','AIR-11','AIR-13','AIR-15'],S2:['PRS-01','PRS-02','PRS-03','PRS-07','PRS-08','PRS-09','PRS-10','PRS-11'],S3:['ACT-01','ACT-03','ACT-04','ACT-06','ACT-10'],S4:['TUR-01','TUR-03','TUR-04','TUR-05','TUR-07','TUR-09','TUR-10'],S5:['X-01','X-06','X-10','X-13','X-14'],S6:['RET-01','RET-02','RET-03','RET-04','RET-05','RET-06','RET-08']};
const defaultDrafts=()=>Object.fromEntries(questionBlocks.filter(q=>q.fields.length).map(q=>[q.id,Object.fromEntries(q.fields.map(f=>[f.id,f.defaultValue]))]));
const seedCase=(demo:DemoCase,blank=false):KnowledgeState=>{const answers:Record<string,RecordedAnswer>={};if(!blank)for(const seed of demo.seeds){const q=findQuestion(seed.questionId),o=q.options.find(x=>x.id===seed.optionId);if(o)answers[q.id]={questionId:q.id,optionId:o.id,label:o.label,outcome:o.outcome,fields:seed.fields??Object.fromEntries(q.fields.map(f=>[f.id,f.defaultValue])),note:'',caseId:demo.id};}const area=blank?'boost-air':demo.startArea;const first=cardsForArea(area)[0];return{caseId:demo.id,pendingCaseId:null,confirmedIntake:null,frozenAreaOrder:null,selectedAreaId:area,selectedCardId:first.id,openQuestionId:first.questionIds[0]??null,answers,historicalIds:[],drafts:defaultDrafts(),notes:{},showIntake:true,showRetest:false,showHistory:false,showAllIssues:false,expandedAreas:[],assetId:null,assetZoom:100,blank};};
export const createInitialKnowledgeState=():KnowledgeState=>{const first=cardsForArea('boost-air')[0];return{caseId:'manual',pendingCaseId:null,confirmedIntake:null,frozenAreaOrder:null,selectedAreaId:'boost-air',selectedCardId:first.id,openQuestionId:first.questionIds[0]??null,answers:{},historicalIds:[],drafts:defaultDrafts(),notes:{},showIntake:true,showRetest:false,showHistory:false,showAllIssues:false,expandedAreas:[],assetId:null,assetZoom:100,blank:true};};
export function answersFromIntake(profile:IntakeProfile):Record<string,RecordedAnswer>{
 const dtcs=intakeDtcSignals(profile);
 const selections:Record<string,string>={'IN-01':profile.engineCode.trim().toUpperCase()==='DKVB'?'dkvb':'other','IN-02':profile.symptomCondition,'IN-04':dtcs.p0299State,'IN-05':dtcs.boostDtcs,'IN-06':dtcs.crossDtcs,'IN-08':profile.safetyGate};
 const answers:Record<string,RecordedAnswer>={};
 for(const [id,value] of Object.entries(selections)){const q=findQuestion(id),o=q.options.find(x=>x.id===value);if(o)answers[id]={questionId:id,optionId:o.id,label:o.label,outcome:o.outcome,fields:{},note:['IN-04','IN-05','IN-06'].includes(id)?dtcs.codes.join('、'):'',caseId:'manual'};}
 return answers;
}
export const answer=(s:KnowledgeState,id:string)=>s.answers[id];
export const isHistorical=(s:KnowledgeState,id:string)=>s.historicalIds.includes(id);
export const activeAnswers=(s:KnowledgeState,stage?:StageId)=>Object.values(s.answers).filter(a=>!isHistorical(s,a.questionId)&&(!stage||findQuestion(a.questionId).stage===stage));
const choice=(s:KnowledgeState,id:string)=>isHistorical(s,id)?undefined:answer(s,id)?.optionId;
const identityReady=(s:KnowledgeState)=>choice(s,'IN-01')==='dkvb'&&['none','caution'].includes(choice(s,'IN-08')??'')&&(!s.confirmedIntake||intakeApplicability(s.confirmedIntake)==='supported');
const crossSignal=(s:KnowledgeState)=>{const v=choice(s,'IN-06');return Boolean(v&&v!=='none'&&v!=='unavailable');};
export function stageEntry(s:KnowledgeState,stage:StageId):{entryState:EntryState;reason:string}{
 if(stage==='S0')return{entryState:required.S0.every(id=>answer(s,id))?'completed':activeAnswers(s,'S0').length?'in_progress':'ready',reason:'先确认身份、症状、故障码和安全边界。'};
 if(!identityReady(s))return{entryState:choice(s,'IN-01')==='other'?'unavailable':'waiting_prerequisite',reason:choice(s,'IN-01')==='other'?'发动机代码不是DKVB，不能直接套用本专题。':'缺少前置事实：请确认DKVB发动机代码并排除立即停止风险。'};
 let suggested=stage==='S1'||stage==='S2';
 if(stage==='S3')suggested=choice(s,'PRS-11')==='persistent_underboost'||['p0236_family','p2261_family','both'].includes(choice(s,'IN-05')??'');
 if(stage==='S4')suggested=choice(s,'ACT-10')==='still_underboost'||activeAnswers(s,'S4').some(a=>a.outcome==='abnormal');
 if(stage==='S5')suggested=choice(s,'ACT-10')==='boost_ok_symptom_remains'||crossSignal(s)||activeAnswers(s,'S5').length>0;
 if(stage==='S6')suggested=activeAnswers(s).some(a=>findQuestion(a.questionId).stage!=='S0'&&(a.outcome==='abnormal'||a.outcome==='unavailable'))||activeAnswers(s,'S6').length>0;
 const ids=questionBlocks.filter(q=>q.stage===stage).map(q=>q.id),stored=ids.filter(id=>answer(s,id)),active=stored.filter(id=>!isHistorical(s,id));
 if(stored.length&&active.length===0)return{entryState:'historical_completed',reason:'历史记录，当前路径已改变；记录保留但不参与当前结论。'};
 if(required[stage].every(id=>active.includes(id)))return{entryState:'completed',reason:'必需问题已记录；“已完成”不表示部件正常。'};
 if(active.length)return{entryState:'in_progress',reason:suggested?'已有本轮有效记录。':'当前为次要方向，已有记录仍保持有效。'};
 if(suggested)return{entryState:'ready',reason:stage==='S4'?'持续低增压或直接外部线索支持进入本区域。':stage==='S5'?'增压恢复但症状仍在，或存在跨系统故障码。':'当前事实建议进入本区域。'};
 return{entryState:'available_secondary',reason:'可以查看和补充记录，但不是当前第一优先。'};
}
export function areaView(s:KnowledgeState,areaId:AreaId){const area=findArea(areaId),entry=stageEntry(s,area.stage),ids=questionBlocks.filter(q=>q.stage===area.stage).map(q=>q.id),done=ids.filter(id=>answer(s,id)).length,active=ids.filter(id=>answer(s,id)&&!isHistorical(s,id)),abnormal=active.filter(id=>answer(s,id)?.outcome==='abnormal').length,firstPass=s.confirmedIntake&&!activeAnswers(s).some(a=>findQuestion(a.questionId).stage!=='S0'),suggested=firstPass&&initialAreaForIntake(s.confirmedIntake!)===areaId&&['ready','in_progress'].includes(entry.entryState);return{...entry,done,total:ids.length,abnormal,sortTier:suggested?0:entry.entryState==='ready'||entry.entryState==='in_progress'?1:entry.entryState==='completed'?2:entry.entryState==='available_secondary'?3:4};}
export function rankedAreas(s:KnowledgeState){return prototypeAreas.map(area=>({area,view:areaView(s,area.id)})).sort((a,b)=>s.frozenAreaOrder?s.frozenAreaOrder.indexOf(a.area.id)-s.frozenAreaOrder.indexOf(b.area.id):a.view.sortTier-b.view.sortTier||a.area.initialPriority-b.area.initialPriority).map((item,index)=>({...item,rank:index+1}));}
export function cardView(s:KnowledgeState,cardId:string){const c=findCard(cardId),done=c.questionIds.filter(id=>answer(s,id)).length,abnormal=c.questionIds.filter(id=>answer(s,id)?.outcome==='abnormal'&&!isHistorical(s,id)).length,historical=done>0&&c.questionIds.filter(id=>answer(s,id)).every(id=>isHistorical(s,id));return{done,total:c.questionIds.length,abnormal,historical};}
const numeric=(s:KnowledgeState,id:string,field:string)=>Number((answer(s,id)?.fields??s.drafts[id]??{})[field]);
export function pressureSummary(s:KnowledgeState){const ambient=numeric(s,'PRS-01','hpa'),g31=numeric(s,'PRS-02','hpa'),g71=numeric(s,'PRS-03','hpa');const vals=[ambient,g31,g71],valid=vals.every(Number.isFinite),maxDelta=valid?Math.max(...vals)-Math.min(...vals):null;let staticClass='等待三个静态值';if(maxDelta!==null)staticClass=maxDelta<=30?'静态一致':Math.abs(g31-ambient)>30&&Math.abs(g71-ambient)<=30?'G31离群':Math.abs(g71-ambient)>30&&Math.abs(g31-ambient)<=30?'G71离群':'多值异常';const frames=[8,9,10].map(n=>({target:numeric(s,`PRS-${n.toString().padStart(2,'0')}`,'target'),actual:numeric(s,`PRS-${n.toString().padStart(2,'0')}`,'actual')}));const deltas=frames.map(x=>Number.isFinite(x.target)&&Number.isFinite(x.actual)?x.target-x.actual:null);let trend='等待三帧数据';if(deltas.every(x=>x!==null))trend=choice(s,'PRS-07')!=='comparable'?'工况不可比':deltas.every(x=>(x??0)>250)?'连续偏低':deltas.every(x=>Math.abs(x??999)<=150)?'持续跟随':'间歇掉压';return{ambient,g31,g71,maxDelta,staticClass,deltas,trend};}
export function optionsFor(s:KnowledgeState,id:string):OptionDef[]{const q=findQuestion(id);if(id==='PRS-04'){const x=pressureSummary(s).staticClass,map:Record<string,string>={'静态一致':'consistent','G31离群':'g31_outlier','G71离群':'g71_outlier','多值异常':'multiple_outliers'};return q.options.filter(o=>o.id===(map[x]??'unavailable')||o.id==='unavailable');}if(id==='PRS-11'){const t=pressureSummary(s).trend,map:Record<string,string>={'持续跟随':'tracks_target','连续偏低':'persistent_underboost','间歇掉压':'intermittent_drop','工况不可比':'unreliable'};return q.options.filter(o=>o.id===(map[t]??'unreliable'));}if(id==='TUR-09'){const n=['TUR-01','TUR-02','TUR-03','TUR-04','TUR-05','TUR-06','TUR-07','TUR-08'].filter(x=>answer(s,x)?.outcome==='abnormal'&&!isHistorical(s,x)).length;return q.options.filter(o=>o.id===(n>=2?'multiple_supporting_facts':n===1?'weak_support':'no_support'));}if(id==='X-13'){const ids:string[]=[];if(['random','cyl1','cyl2','cyl3','cyl4'].includes(choice(s,'X-01')??'')||['moved_with_coil','moved_with_plug'].includes(choice(s,'X-05')??''))ids.push('ignition');if(choice(s,'X-08')==='falls_under_load'||['low_pressure','high_pressure'].includes(choice(s,'X-06')??''))ids.push('fuel');if(['restriction_clue','overheat_clue','rattle'].includes(choice(s,'X-10')??''))ids.push('exhaust');const target=ids.length>1?'multiple':ids[0]??'none';return q.options.filter(o=>o.id===target);}return q.options;}
export function activeResultStates(s:KnowledgeState):ResultStateDef[]{const abnormal=(...ids:string[])=>ids.some(id=>answer(s,id)?.outcome==='abnormal'&&!isHistorical(s,id));const strongLeak=Boolean(choice(s,'AIR-15')&&choice(s,'AIR-15')!=='none'&&['audible_or_bubble','ultrasonic'].includes(choice(s,'AIR-16')??''));const matches:Record<string,boolean>={R01:choice(s,'IN-01')==='unknown',R02:choice(s,'IN-08')==='stop_now',R03:abnormal('AIR-01','AIR-02'),R04:abnormal('AIR-03'),R05:abnormal('AIR-04'),R06:abnormal('AIR-07','AIR-08'),R07:abnormal('AIR-09','AIR-10'),R08:abnormal('AIR-11','AIR-12'),R09:strongLeak,R10:['AIR-01','AIR-02','AIR-03','AIR-04','AIR-07','AIR-08','AIR-09','AIR-10','AIR-11','AIR-12','AIR-16'].every(id=>Boolean(answer(s,id))&&!abnormal(id)),R11:choice(s,'PRS-04')==='g31_outlier',R12:choice(s,'PRS-04')==='g71_outlier',R13:choice(s,'PRS-07')!==undefined&&(choice(s,'PRS-07')!=='comparable'||choice(s,'PRS-11')==='unreliable'),R14:choice(s,'PRS-11')==='persistent_underboost',R15:abnormal('ACT-01','ACT-02'),R16:['no','jerky'].includes(choice(s,'ACT-03')??''),R17:abnormal('ACT-04','ACT-05'),R18:abnormal('ACT-06','ACT-07'),R19:choice(s,'ACT-10')==='recovered',R20:choice(s,'ACT-10')==='still_underboost',R21:['no_support','weak_support'].includes(choice(s,'TUR-09')??''),R22:choice(s,'TUR-09')==='multiple_supporting_facts',R23:choice(s,'X-13')==='ignition',R24:choice(s,'X-13')==='fuel',R25:choice(s,'X-13')==='exhaust',R26:['RET-04','RET-05','RET-06','RET-07','RET-08'].some(id=>Boolean(answer(s,id))&&!isHistorical(s,id))};return resultStates.filter(r=>matches[r.id]);}
export function explanation(s:KnowledgeState){const supports=activeAnswers(s).filter(a=>(a.outcome==='abnormal'||a.outcome==='unavailable')&&!(findQuestion(a.questionId).stage==='S0'&&a.outcome==='unavailable')).map(a=>a.questionId);let text='当前仍在收集能够解释主诉的有效事实。';if(choice(s,'IN-08')==='stop_now')text='存在安全停止事实，当前不继续负荷检查。';else if(choice(s,'PRS-04')==='g31_outlier'&&['harness_damage','loose'].includes(choice(s,'PRS-05')??''))text='静态离群与连接/线束线索共同支持G31信号路径优先。';else if(choice(s,'TUR-09')==='multiple_supporting_facts')text='至少两类独立外部事实支持涡轮本体方向，需要专业检测但尚未确诊内部损坏。';else if(choice(s,'X-13')==='ignition')text='失火故障码与部件对调结果共同支持点火方向。';else if(choice(s,'X-13')==='fuel')text='燃油故障码与负荷下高压掉压共同支持燃油方向。';else if(choice(s,'X-14')==='conflicting_facts')text='多个方向同时存在但证据均不足，当前为冲突保守交接。';else if(choice(s,'AIR-15')&&choice(s,'AIR-15')!=='none'&&['audible_or_bubble','ultrasonic'].includes(choice(s,'AIR-16')??''))text='泄漏位置与强定位证据共同支持空气通路泄漏。';return{text,supports:supports.slice(0,6)};}
export function reducer(s:KnowledgeState,e:KnowledgeEvent):KnowledgeState{if(e.type==='request-case')return{...s,pendingCaseId:e.caseId};if(e.type==='cancel-case')return{...s,pendingCaseId:null};if(e.type==='confirm-case'){const c=demoCases.find(x=>x.id===s.pendingCaseId)??demoCases[0];return seedCase(c);}if(e.type==='reset-case')return seedCase(demoCases.find(x=>x.id===s.caseId)??demoCases[0]);if(e.type==='blank')return seedCase(demoCases.find(x=>x.id===s.caseId)??demoCases[0],true);if(e.type==='select-area'){const c=cardsForArea(e.areaId)[0];return{...s,selectedAreaId:e.areaId,selectedCardId:c.id,openQuestionId:c.questionIds[0]??null};}if(e.type==='select-card'){const c=findCard(e.cardId);return{...s,selectedCardId:c.id,openQuestionId:c.questionIds[0]??null};}if(e.type==='open-question')return{...s,openQuestionId:e.questionId};if(e.type==='update-draft')return{...s,drafts:{...s.drafts,[e.questionId]:{...(s.drafts[e.questionId]??{}),[e.field]:e.value}}};if(e.type==='update-note')return{...s,notes:{...s.notes,[e.questionId]:e.value}};if(e.type==='record'){const q=findQuestion(e.questionId),o=optionsFor(s,q.id).find(x=>x.id===e.optionId)??q.options.find(x=>x.id===e.optionId);if(!o)return s;return{...s,answers:{...s.answers,[q.id]:{questionId:q.id,optionId:o.id,label:o.label,outcome:o.outcome,fields:s.drafts[q.id]??{},note:s.notes[q.id]??'',caseId:s.caseId}},historicalIds:s.historicalIds.filter(id=>id!==q.id)};}if(e.type==='correct'){const q=findQuestion(e.questionId),cut=stageOrder.indexOf(q.stage),history=new Set(s.historicalIds);for(const a of Object.values(s.answers))if(stageOrder.indexOf(findQuestion(a.questionId).stage)>cut)history.add(a.questionId);const answers={...s.answers};delete answers[q.id];return{...s,answers,historicalIds:[...history],openQuestionId:q.id};}if(e.type==='toggle-intake')return{...s,showIntake:!s.showIntake};if(e.type==='toggle-retest')return{...s,showRetest:!s.showRetest};if(e.type==='toggle-history')return{...s,showHistory:!s.showHistory};if(e.type==='toggle-issues')return{...s,showAllIssues:!s.showAllIssues};if(e.type==='toggle-area')return{...s,expandedAreas:s.expandedAreas.includes(e.areaId)?s.expandedAreas.filter(x=>x!==e.areaId):[...s.expandedAreas,e.areaId]};if(e.type==='open-asset')return{...s,assetId:e.assetId,assetZoom:100};if(e.type==='close-asset')return{...s,assetId:null};if(e.type==='zoom-asset')return{...s,assetZoom:e.zoom};return s;}
export function reducerWithIntake(s:KnowledgeState,e:KnowledgeEvent):KnowledgeState{
 if(e.type!=='confirm-intake')return reducer(s,e);
 const profile=e.profile,changed=Boolean(s.confirmedIntake&&JSON.stringify(s.confirmedIntake)!==JSON.stringify(profile));
 const history=new Set(s.historicalIds);
 if(changed)for(const a of Object.values(s.answers))if(findQuestion(a.questionId).stage!=='S0')history.add(a.questionId);
 const previous=Object.fromEntries(Object.entries(s.answers).filter(([id])=>findQuestion(id).stage!=='S0'));
 const intakeAnswers=answersFromIntake(profile);
 const initial={...s,caseId:'manual',confirmedIntake:profile,frozenAreaOrder:null,answers:intakeAnswers,historicalIds:[],showIntake:false,blank:false};
 const frozenAreaOrder=rankedAreas(initial).map(item=>item.area.id);
 const firstArea=frozenAreaOrder[0],firstCard=cardsForArea(firstArea)[0];
 return {...initial,answers:{...previous,...intakeAnswers},historicalIds:[...history],frozenAreaOrder,selectedAreaId:firstArea,selectedCardId:firstCard.id,openQuestionId:firstCard.questionIds[0]??null};
}
